     3→namespace App\Http\Repositories\Empresas;
     4→
     5→use App\Models\Planes\Plan;
     6→use Illuminate\Http\Request;
     7→use App\Models\Pruebas\TipoPrueba;
     8→use Illuminate\Support\Collection;
     9→use Illuminate\Support\Facades\DB;
    10→use App\Models\Empresas\EmpresaPlan;
    11→use App\Http\Repositories\BaseRepository;
    12→use App\Http\Repositories\Permisos\RolRepository;
    13→use App\Interfaces\Repositorios\ObtenerUnoAvanzado;
    14→
    15→class EmpresaPlanRepository extends BaseRepository implements ObtenerUnoAvanzado
    16→{
    17→    /**
    18→     * Ids de los roles de tipo empresa.
    19→     *
    20→     * @var array
    21→     * @author Fahibram Cárcamo
    22→     * @author Daniel Beltrán
    23→     */
    24→    private const ROLES_TIPO_EMPRESA_IDS = [
    25→        RolRepository::ROL_PROPIETARIO_ID,
    26→        RolRepository::ROL_ADMINISTRADOR_GENERAL_ID,
    27→        RolRepository::ROL_ADMINISTRADOR_SUCURSAL_ID,
    28→        RolRepository::ROL_EVALUADOR_ID
    29→    ];
    30→
    31→    private $consulta_conteo_total_usuarios_empresa_sucursales;
    32→    private $consulta_conteo_total_consumos_agendas_empresa_sucursales;
    33→    private $consulta_conteo_total_consumos_ofertas_laborales_empresa_sucursales;
    34→    private $consulta_conteo_total_consumos_creditos;
    35→
    36→    /**
    37→     * Constructor.
    38→     *
    39→     * @param EmpresaPlan $modelo Modelo de planes de empresas.
    40→     * @return void
    41→     * @author Daniel Beltrán
    42→     * @author Fahibram Cárcamo
    43→     */
    44→    public function __construct(EmpresaPlan $modelo) {
    45→        $this->consulta_conteo_total_usuarios_empresa_sucursales = '
    46→            (
    47→                SELECT COUNT(DISTINCT eu.usuario_id)
    48→                FROM empresas_usuarios AS eu
    49→                LEFT JOIN empresas AS s ON eu.empresa_id = s.id
    50→                WHERE (eu.empresa_id = empresas_planes.empresa_id OR s.empresa_id = empresas_planes.empresa_id)
    51→                AND eu.rol_id IN (' . implode(',', self::ROLES_TIPO_EMPRESA_IDS) . ')
    52→            ) AS conteo_total_usuarios_empresa_sucursales
    53→        ';
    54→
    55→        $this->consulta_conteo_total_consumos_agendas_empresa_sucursales = '
    56→            (
    57→                SELECT COUNT(*)
    58→                FROM consumos
    59→                LEFT JOIN empresas AS s ON consumos.empresa_id = s.id
    60→                WHERE (
    61→                    consumos.empresa_id = empresas_planes.empresa_id
    62→                    OR s.empresa_id = empresas_planes.empresa_id
    63→                )
    64→                AND consumos.agenda_id IS NOT NULL
    65→            ) AS conteo_total_consumos_agendas_empresa_sucursales
    66→        ';
    67→
    68→        $this->consulta_conteo_total_consumos_ofertas_laborales_empresa_sucursales = '
    69→            (
    70→                SELECT COUNT(*)
    71→                FROM consumos
    72→                LEFT JOIN empresas AS s ON consumos.empresa_id = s.id
    73→                WHERE (
    74→                    consumos.empresa_id = empresas_planes.empresa_id
    75→                    OR s.empresa_id = empresas_planes.empresa_id
    76→                )
    77→                AND consumos.oferta_laboral_id IS NOT NULL
    78→            ) AS conteo_total_consumos_ofertas_laborales_empresa_sucursales
    79→        ';
    80→
    81→        $this->consulta_conteo_total_consumos_creditos = '
    82→            (
    83→                SELECT COUNT(*)
    84→                FROM consumos_creditos
    85→                WHERE consumos_creditos.empresa_plan_id = empresas_planes.id
    86→            ) AS conteo_total_consumos_creditos
    87→        ';
    88→
    89→        parent::__construct($modelo);
    90→    }
    91→
    92→    /**
    93→     * Obtener todos los planes de empresas.
    94→     *
    95→     * @param Request $request Contenido de la petición.
    96→     * @return Collection
    97→     * @author Daniel Beltrán
    98→     * @author Fahibram Cárcamo
    99→     * @author Jair Carvajal
   100→     * @author Andres Gonzalez
   101→     */
   102→    public function getTodo(Request $request): Collection {
   103→        $con_consumos_agendas = $request->filled('con_consumos_agendas')
   104→            && filter_var($request->con_consumos_agendas, FILTER_VALIDATE_BOOLEAN);
   105→        $con_consumos_ofertas_laborales = $request->filled('con_consumos_ofertas_laborales')
   106→            && filter_var($request->con_consumos_ofertas_laborales, FILTER_VALIDATE_BOOLEAN);
   107→        $con_conteo_consumos_agendas = $request->filled('con_conteo_consumos_agendas')
   108→            && filter_var($request->con_conteo_consumos_agendas, FILTER_VALIDATE_BOOLEAN);
   109→        $con_conteo_consumos_ofertas_laborales = $request->filled('con_conteo_consumos_ofertas_laborales')
   110→            && filter_var($request->con_conteo_consumos_ofertas_laborales, FILTER_VALIDATE_BOOLEAN);
   111→        $con_conteo_consumos_creditos = $request->filled('con_conteo_consumos_creditos')
   112→            && filter_var($request->con_conteo_consumos_creditos, FILTER_VALIDATE_BOOLEAN);
   113→
   114→        return $this->modelo::select('id', 'empresa_id', 'plan_id', 'plan_credito_id', 'estado_id', 'unidades', 'cantidad_ofertas_laborales', 'cantidad_usuarios', 'cantidad_pruebas', 'creditos', 'fecha_inicio', 'fecha_vencimiento', 'precio', 'porcentaje_descuento', 'numero_factura', 'comentario', 'plan_original', 'renovando', 'por_facturar', 'created_at')
   115→        ->with([
   116→            'plan:id,tipo_prueba_id,nombre,cantidad_pruebas,cantidad_usuarios,cantidad_ofertas_laborales,unidades,vigencia,precio',
   117→            'empresa:id,empresa_id,nombre_comercial,razon_social',
   118→            'plan.tipoPrueba:id,nombre',
   119→            'planCredito:id,nombre,creditos,precio,porcentaje_descuento,fecha_inicio_promocion,fecha_fin_promocion',
   120→            'estado:id,nombre',
   121→            'pruebas:id,nombre',
   122→            'funcionalidades:id,nombre,predeterminado',
   123→            'archivos' => function ($archivos) {
   124→                $archivos->select('id', 'modelo', 'modelo_id', 'nombre', 'ruta', 'created_at')->orderBy('created_at', 'DESC');
   125→            }
   126→        ])
   127→        ->when($con_consumos_agendas || $con_consumos_ofertas_laborales, function ($query) use ($con_consumos_agendas, $con_consumos_ofertas_laborales) {
   128→            $query->with([
   129→                'consumos' => function ($consumos) use ($con_consumos_agendas, $con_consumos_ofertas_laborales) {
   130→                    $consumos->select('id', 'empresa_plan_id', 'empresa_id', 'agenda_id', 'oferta_laboral_id')
   131→                        ->with(['empresa' => function ($empresa) {
   132→                            $empresa->select('id', 'empresa_id', 'nombre_comercial', 'razon_social')->with('usuarios:id,nombres,apellidos');
   133→                        }])
   134→                        ->when($con_consumos_agendas, fn($consulta) => $consulta->whereNotNull('agenda_id'))
   135→                        ->when($con_consumos_ofertas_laborales, fn($consulta) => $consulta->orWhereNotNull('oferta_laboral_id'));
   136→                },
   137→                'consumos.agenda:id,prueba_id',
   138→                'consumos.agenda.prueba:id,nombre,slug'
   139→            ]);
   140→        })
   141→        ->when($con_conteo_consumos_agendas, function ($consulta) {
   142→            $consulta->withCount(['consumos as conteo_consumos_agendas' => fn($consulta_consumos) => $consulta_consumos->whereNotNull('agenda_id')]);
   143→        })
   144→        ->when($con_conteo_consumos_ofertas_laborales, function ($consulta) {
   145→            $consulta->withCount(['consumos as conteo_consumos_ofertas_laborales' => fn($consulta_consumos) => $consulta_consumos->whereNotNull('oferta_laboral_id')]);
   146→        })
   147→        ->when($request->filled('contar_consumos_vacantes') && filter_var($request->contar_consumos_vacantes, FILTER_VALIDATE_BOOLEAN), function ($consulta) use ($request) {
   148→            $consulta->withCount([
   149→                'consumos as conteo_consumos_vacantes' => function ($consumos) use ($request) {
   150→                    $consumos->whereNotNull('vacante_id');
   151→
   152→                    if ($request->filled('empresa_id')) {
   153→                        $consumos->where('empresa_id', $request->empresa_id);
   154→                    }
   155→                }
   156→            ]);
   157→        })
   158→        ->when($con_conteo_consumos_creditos, function ($consulta) {
   159→            $consulta->withSum('consumosCreditos as creditos_consumidos', 'creditos');
   160→        })
   161→        ->when($request->filled('empresa_id'), function ($query) use ($request) {
   162→            $query->where('empresa_id', $request->empresa_id);
   163→        })
   164→        ->when($request->filled('tipo_prueba_id'), function ($query) use ($request) {
   165→            $query->whereHas('plan', function ($plan) use ($request) {
   166→                $plan->where('tipo_prueba_id', $request->tipo_prueba_id);
   167→            });
   168→        })
   169→        ->when($request->filled('nombre_plan'), function ($query) use ($request) {
   170→            $query->whereHas('plan', function ($plan) use ($request) {
   171→                $plan->where('nombre', 'like', "%{$request->nombre_plan}%");
   172→            });
   173→        })
   174→        ->when($request->filled('plan_id'), fn($consulta) => $consulta->where('plan_id', $request->plan_id))
   175→        ->when($request->filled('es_plan_creditos') && $request->es_plan_creditos, fn($consulta) => $consulta->whereNotNull('plan_credito_id'))
   176→        ->when(
   177→            $request->has('en') && filter_var($request->en, FILTER_VALIDATE_BOOLEAN) && $request->filled('campo') && $request->filled('valores'),
   178→            function ($query) use ($request) {
   179→                $query->whereIn($request->campo, $request->valores);
   180→            }
   181→        )
   182→        ->when($request->filled('estado_id'), fn($consulta) => $consulta->where('estado_id', $request->estado_id))
   183→        ->when($request->filled('estados_ids'), fn($consulta) => $consulta->whereIn('estado_id', $request->estados_ids))
   184→        ->when(
   185→            $request->filled('duracion') && $request->duracion === 'con_tiempo',
   186→            fn($consulta) => $consulta->whereNotNull('fecha_vencimiento')
   187→        )
   188→        ->when(
   189→            $request->filled('duracion') && $request->duracion === 'sin_tiempo',
   190→            fn($consulta) => $consulta->whereNull('fecha_vencimiento')
   191→        )
   192→        ->when(
   193→            $request->filled('fecha_vencimiento_desde'),
   194→            fn($consulta) => $consulta->where('fecha_vencimiento', '>=', $request->fecha_vencimiento_desde)
   195→        )
   196→        ->when(
   197→            $request->filled('fecha_vencimiento_hasta'),
   198→            fn($consulta) => $consulta->where('fecha_vencimiento', '<=', $request->fecha_vencimiento_hasta)
   199→        )
   200→        ->when(
   201→            $request->filled('fecha_inicio_desde'),
   202→            fn($consulta) => $consulta->where('fecha_inicio', '>=', $request->fecha_inicio_desde)
   203→        )
   204→        ->when(
   205→            $request->filled('fecha_inicio_hasta'),
   206→            fn($consulta) => $consulta->where('fecha_inicio', '<=', $request->fecha_inicio_hasta)
   207→        )
   208→        ->orderBy('created_at', 'DESC')
   209→        ->get();
   210→    }
