   212→    /**
   213→     * Obtener todas las suscripciones de planes que hayan sido recompradas para mostrarlas a un usuario con rol Superadministrador.
   214→     *
   215→     * @param Request $request Contenido de la petición HTTP entrante.
   216→     * @return Collection
   217→     * @author Fahibram Cárcamo
   218→     * @author Jair Carvajal
   219→     * @author Daniel Beltrán
   220→     */
   221→    public function obtenerRecomprasEmpresaParaSuperadmin(Request $request): Collection {
   222→        return $this->modelo->select('id', 'empresa_id', 'plan_id', 'plan_credito_id', 'estado_id', 'unidades', 'cantidad_ofertas_laborales', 'cantidad_usuarios', 'cantidad_pruebas', 'creditos', 'fecha_inicio', 'fecha_vencimiento', 'precio', 'porcentaje_descuento', 'numero_factura', 'comentario', 'plan_original', 'renovando', 'por_facturar', 'created_at')
   223→            ->addSelect([
   224→                DB::raw($this->consulta_conteo_total_usuarios_empresa_sucursales),
   225→                DB::raw($this->consulta_conteo_total_consumos_agendas_empresa_sucursales),
   226→                DB::raw($this->consulta_conteo_total_consumos_ofertas_laborales_empresa_sucursales),
   227→                DB::raw($this->consulta_conteo_total_consumos_creditos)
   228→            ])
   229→            ->whereExists(function ($subconsulta) {
   230→                $subconsulta->select(DB::raw(1))
   231→                    ->from('empresas_planes AS empresas_planes_subconsulta')
   232→                    ->whereColumn('empresas_planes_subconsulta.plan_id', 'empresas_planes.plan_id')
   233→                    ->whereColumn('empresas_planes_subconsulta.empresa_id', 'empresas_planes.empresa_id')
   234→                    ->whereColumn('empresas_planes_subconsulta.id', '<>', 'empresas_planes.id');
   235→            })
   236→            ->with([
   237→                'estado:id,nombre',
   238→                'plan:id,tipo_prueba_id,nombre,vigencia',
   239→                'archivos' => fn($consulta_factura) => $consulta_factura->where('nombre', 'factura')->limit(1)
   240→            ])
   241→            ->when($request->filled('empresa_id'), fn($consulta) => $consulta->where('empresa_id', $request->empresa_id))
   242→            ->when(
   243→                $request->filled('tipo_prueba_id'),
   244→                function ($consulta) use ($request) {
   245→                    $consulta->whereHas('plan', fn($consulta_plan) => $consulta_plan->where('tipo_prueba_id', $request->tipo_prueba_id));
   246→                },
   247→                function ($consulta) {
   248→                    $consulta->whereHas('plan', fn($consulta_plan) => $consulta_plan->whereIn('tipo_prueba_id', [
   249→                        TipoPrueba::SELECCION_ID,
   250→                        TipoPrueba::ORGANIZACIONAL_ID,
   251→                        TipoPrueba::VOCACIONAL_ID
   252→                    ]));
   253→                }
   254→            )
   255→            ->get();
   256→    }
