   279→                    ->whereColumn('empresas_planes_subconsulta.plan_id', 'empresas_planes.plan_id')
   280→                    ->whereColumn('empresas_planes_subconsulta.empresa_id', 'empresas_planes.empresa_id')
   281→                    ->whereColumn('empresas_planes_subconsulta.id', '<>', 'empresas_planes.id');
   282→            }) */
   283→            ->with([
   284→                'estado:id,nombre',
   285→                'plan:id,tipo_prueba_id,nombre,vigencia',
   286→                'plan.tipoPrueba:id,nombre',
   287→                'pruebas:id,nombre,slug',
   288→                'funcionalidades:id,nombre,predeterminado',
   289→                'archivos' => fn($consulta_factura) => $consulta_factura->where('nombre', 'factura')->limit(1),
   290→                'consumos' => function ($consumos) {
   291→                    $consumos->select('id', 'empresa_plan_id', 'empresa_id', 'agenda_id', 'oferta_laboral_id')
   292→                        ->with([
   293→                            'empresa:id,empresa_id,nombre_comercial,razon_social',
   294→                            'agenda:id,prueba_id',
   295→                            'agenda.prueba:id,nombre,slug'
   296→                        ]);
   297→                }
   298→            ])
   299→            ->when($request->filled('con_conteo_consumos_agendas') && filter_var($request->con_conteo_consumos_agendas, FILTER_VALIDATE_BOOLEAN), function ($consulta) use ($request) {
   300→                $consulta->withCount([
   301→                    'consumos as conteo_consumos_agendas' => function ($consumos) use ($request) {
