   312→            })
   313→            ->when($request->filled('contar_consumos_vacantes') && filter_var($request->contar_consumos_vacantes, FILTER_VALIDATE_BOOLEAN), function ($consulta) use ($request) {
   314→                $consulta->withCount([
   315→                    'consumos as conteo_consumos_vacantes' => function ($consumos) use ($request) {
