   332→            ->when($request->filled('empresa_id'), fn($consulta) => $consulta->where('empresa_id', $request->empresa_id))
   333→            ->when($request->filled('tipo_prueba_id'), function ($consulta) use ($request) {
   334→                $consulta->whereHas('plan', fn($consulta_plan) => $consulta_plan->where('tipo_prueba_id', $request->tipo_prueba_id));
   335→            }, function ($consulta) {
