   346→    /**
   347→     * Obtener datos básicos de los planes de empresas.
   348→     *
   349→     * @param Request $request Contenido de la petición.
   350→     * @return Collection
   351→     * @author Daniel Beltrán
   352→     * @author Fahibram Cárcamo
   353→     * @author Jair Carvajal
   354→     * @author Sergio Vargas
   355→     */
   356→    public function getDatosBasicos(Request $request): Collection {
   357→        return $this->modelo::select('id', 'empresa_id', 'plan_id', 'plan_credito_id', 'estado_id', 'unidades', 'cantidad_ofertas_laborales', 'creditos', 'fecha_inicio', 'fecha_vencimiento', 'created_at')
   358→        ->with([
   359→            'plan:id,tipo_prueba_id,nombre',
   360→            'planCredito:id,nombre,creditos',
   361→            'consumosCreditos'
   362→        ])
   363→        ->withCount([
   364→            'consumos as consumos_agendas'           => fn($consumos) => $consumos->whereNotNull('agenda_id'),
   365→            'consumos as consumos_ofertas_laborales' => fn($consumos) => $consumos->whereNotNull('oferta_laboral_id')
   366→        ])
   367→        ->when($request->filled('empresa_id'), function ($consulta) use ($request) {
   368→            $consulta->where('empresa_id', $request->empresa_id);
   369→        })
   370→        ->when($request->filled('tipo_prueba_id'), function ($consulta) use ($request) {
   371→            $consulta->whereHas('plan', function ($plan) use ($request) {
   372→                $plan->where('tipo_prueba_id', $request->tipo_prueba_id);
   373→            });
   374→        })
   375→        ->when($request->filled('estados_ids'), function ($consulta) use ($request) {
   376→            $consulta->whereIn('estado_id', $request->estados_ids);
   377→        })
   378→        ->when($request->filled('ordenar_por'), function ($consulta) use ($request) {
   379→            $sentido = $request->ordenar_sentido ?? 'ASC';
   380→            $consulta->orderBy($request->ordenar_por, $sentido);
   381→        })
   382→        ->get();
   383→    }
