   720→     * @author Jair Carvajal
   721→     * @author Daniel Beltrán
   722→     */
   723→    public function datosConsumosEmpresas(Request $request): Collection {
   724→        $matriz_conteos = [
   725→            'consumos as conteo_consumos_agendas'           => fn($consulta_consumos) => $consulta_consumos->whereNotNull('agenda_id'),
   726→            'consumos as conteo_consumos_ofertas_laborales' => fn($consulta_consumos) => $consulta_consumos->whereNotNull('oferta_laboral_id'),
   727→            'usuarios as conteo_usuarios'                   => fn($consulta_usuarios) => $consulta_usuarios->whereHas(
   728→                'empresasUsuarios',
   729→                fn($consulta_empresas_usuarios) => $consulta_empresas_usuarios->whereIn('rol_id', self::ROLES_TIPO_EMPRESA_IDS)
   730→            )
   731→        ];
   732→
   733→        $campos_empresas = ['id', 'empresa_id', 'nombre_comercial', 'razon_social', 'nombre_contacto', 'celular_contacto', 'email_contacto', 'telefono_contacto', 'extension_contacto', 'nombre_tesorero', 'celular_tesorero', 'telefono_tesorero', 'email_tesorero'];
   734→
   735→        return $this->modelo::select('id', 'empresa_id', 'plan_id', 'plan_credito_id', 'usuario_id', 'estado_id', 'unidades', 'cantidad_ofertas_laborales', 'cantidad_usuarios', 'cantidad_pruebas', 'creditos', 'fecha_inicio', 'fecha_vencimiento', 'precio', 'porcentaje_descuento', 'numero_factura', 'comentario', 'plan_original', 'renovando', 'por_facturar', 'created_at')
   736→            ->addSelect([
   737→                DB::raw($this->consulta_conteo_total_usuarios_empresa_sucursales),
   738→                DB::raw($this->consulta_conteo_total_consumos_agendas_empresa_sucursales),
   739→                DB::raw($this->consulta_conteo_total_consumos_ofertas_laborales_empresa_sucursales),
   740→                DB::raw($this->consulta_conteo_total_consumos_creditos)
   741→            ])
   742→            ->with([
   743→                'plan:id,tipo_prueba_id,nombre,unidades,cantidad_ofertas_laborales,vigencia,precio',
   744→                'plan.tipoPrueba:id,nombre',
   745→                'planCredito:id,nombre,creditos,precio,porcentaje_descuento',
   746→                'pruebas:id,nombre,slug',
   747→                'estado:id,nombre',
   748→                'usuario:id,nombres,apellidos',
   749→                'empresa' => function ($consulta_empresa) use ($matriz_conteos, $campos_empresas) {
   750→                    $consulta_empresa->select($campos_empresas)
   751→                        ->whereNull('empresa_id')
   752→                        ->withCount([
   753→                            ...$matriz_conteos,
   754→                            'sucursales as conteo_sucursales'
   755→                        ])
   756→                        ->with([
   757→                            'sucursales' => function ($consulta_sucursal) use ($matriz_conteos, $campos_empresas) {
   758→                                $consulta_sucursal->select($campos_empresas)->withCount($matriz_conteos);
   759→                            }
   760→                        ]);
   761→                }
   762→            ])
